# -*- coding: utf-8 -*-
from __future__ import annotations

import asyncio
import typing

import llm_router
import pytest
import tests.llm_router.support.builders as builders

pytestmark = pytest.mark.verification_kind("unit")


class _TrackingExecutorWrapper:
    """Wraps an executor to fail on the initial route attempt and track subsequent attempts."""

    def __init__(self, inner: typing.Any = None) -> None:
        self.inner = inner
        self.failed_route: typing.Any = None
        self.failed_route_attempts: int = 0
        self.fallback_attempts: int = 0

    def _is_target_route(self, request: typing.Any) -> bool:
        route = getattr(request, "route", None)
        if self.failed_route is None:
            self.failed_route = route
            return True
        if route is None:
            return False
        if route == self.failed_route:
            return True
        for attr in ("route_id", "name", "model"):
            route_val = getattr(route, attr, None)
            target_val = getattr(self.failed_route, attr, None)
            if route_val is not None and target_val is not None and route_val == target_val:
                return True
        return False

    def _make_dummy_response(self, request: typing.Any) -> typing.Any:
        if hasattr(builders, "build_response"):
            try:
                return builders.build_response()
            except Exception:
                pass

        class _DummyResponse:
            text: str = "normalized fallback response"
            content: str = "normalized fallback response"
            status_code: int = 200

        return _DummyResponse()

    async def execute_async(self, request: typing.Any, *args: typing.Any, **kwargs: typing.Any) -> typing.Any:
        if self._is_target_route(request):
            self.failed_route_attempts += 1
            raise RuntimeError("Simulated provider failure on target route")
        self.fallback_attempts += 1
        if self.inner is not None and hasattr(self.inner, "execute_async"):
            return await self.inner.execute_async(request, *args, **kwargs)
        if self.inner is not None and callable(self.inner):
            res = self.inner(request, *args, **kwargs)
            if asyncio.iscoroutine(res):
                return await res
            return res
        return self._make_dummy_response(request)

    async def call_async(self, request: typing.Any, *args: typing.Any, **kwargs: typing.Any) -> typing.Any:
        return await self.execute_async(request, *args, **kwargs)

    async def aexecute(self, request: typing.Any, *args: typing.Any, **kwargs: typing.Any) -> typing.Any:
        return await self.execute_async(request, *args, **kwargs)

    def execute(self, request: typing.Any, *args: typing.Any, **kwargs: typing.Any) -> typing.Any:
        if self._is_target_route(request):
            self.failed_route_attempts += 1
            raise RuntimeError("Simulated provider failure on target route")
        self.fallback_attempts += 1
        if self.inner is not None and hasattr(self.inner, "execute"):
            return self.inner.execute(request, *args, **kwargs)
        if self.inner is not None and callable(self.inner):
            return self.inner(request, *args, **kwargs)
        return self._make_dummy_response(request)

    def execute_sync(self, request: typing.Any, *args: typing.Any, **kwargs: typing.Any) -> typing.Any:
        return self.execute(request, *args, **kwargs)

    def call_sync(self, request: typing.Any, *args: typing.Any, **kwargs: typing.Any) -> typing.Any:
        return self.execute(request, *args, **kwargs)

    def __call__(self, request: typing.Any, *args: typing.Any, **kwargs: typing.Any) -> typing.Any:
        if self.inner is not None and asyncio.iscoroutinefunction(getattr(self.inner, "__call__", None)):
            return self.execute_async(request, *args, **kwargs)
        return self.execute(request, *args, **kwargs)


def _build_test_router() -> typing.Any:
    """Build a multi-route test router using project builders or LLMRouter."""
    if hasattr(builders, "build_router"):
        for kwargs in (
            {},
            {"spec": "mock-a -> mock-b"},
            {"spec": "openai/gpt-4o -> anthropic/claude-3-5-sonnet"},
        ):
            try:
                r = builders.build_router(**kwargs)
                rt = getattr(r, "_runtime", r)
                routes = getattr(getattr(rt, "route_plan", None), "routes", None)
                if routes and len(routes) >= 2:
                    return r
                if hasattr(rt, "route_plan"):
                    return r
            except Exception:
                continue

    if hasattr(builders, "build_route") and hasattr(builders, "build_router"):
        try:
            r1 = builders.build_route(name="primary-route")
            r2 = builders.build_route(name="fallback-route")
            return builders.build_router(routes=[r1, r2])
        except Exception:
            pass

    if hasattr(builders, "RouterBuilder"):
        try:
            return builders.RouterBuilder().build()
        except Exception:
            pass

    llm_router_cls = getattr(llm_router, "LLMRouter", None)
    if llm_router_cls is not None:
        for spec in (
            "mock-a -> mock-b",
            "openai/gpt-4o -> anthropic/claude-3-5-sonnet",
            "primary -> fallback",
        ):
            try:
                return llm_router_cls(spec=spec)
            except Exception:
                continue

    raise RuntimeError("Could not construct test router with available builders")


@pytest.mark.verifies("REQ_ASYNC_PROVIDER_EXECUTION[revision==1]")
@pytest.mark.asyncio
async def test_async_provider_execution_records_failure_and_blocks_cooled_down_route() -> None:
    """Make one async attempt fail on a route, then verify the failure is recorded

    and the next async request blocks/skips the route identically to the sync path.
    """
    # 1. Establish the baseline behavior on the sync path
    sync_router = _build_test_router()
    sync_runtime = getattr(sync_router, "_runtime", sync_router)
    sync_executor = _TrackingExecutorWrapper(sync_runtime._executor)
    sync_runtime._executor = sync_executor

    sync_router.query("first sync request")
    assert sync_executor.failed_route_attempts == 1
    assert sync_executor.fallback_attempts == 1

    sync_router.query("second sync request")
    # Sync path records failure, so the second sync request blocks/skips the cooled-down route
    assert sync_executor.failed_route_attempts == 1
    assert sync_executor.fallback_attempts == 2

    # 2. Test the async path under the same conditions
    async_router = _build_test_router()
    async_runtime = getattr(async_router, "_runtime", async_router)
    async_executor = _TrackingExecutorWrapper(async_runtime._executor)
    async_runtime._executor = async_executor

    # First async query fails on the initial route and succeeds on fallback
    await async_router.aquery("first async request")
    assert async_executor.failed_route_attempts == 1
    assert async_executor.fallback_attempts == 1

    # Verify that the target route was recorded as cooled down / unhealthy in the runtime
    target_route = async_executor.failed_route
    settings = async_runtime._settings_for_route(route=target_route, call_overrides={})
    _, wait_seconds = async_runtime._prepare_request(
        request_id="verification_probe",
        route=target_route,
        settings=settings,
        content="verification_probe",
    )
    assert wait_seconds > 0, (
        f"Expected route {target_route} to be recorded as cooled down with wait_seconds > 0, "
        f"got wait_seconds={wait_seconds}"
    )

    # Second async query: should block or skip the cooled-down route just as the sync path does
    response2 = await async_router.aquery("second async request")
    assert async_executor.failed_route_attempts == 1, (
        "Subsequent async request did not block or skip the cooled-down route; "
        f"expected 1 failed route attempt, got {async_executor.failed_route_attempts}"
    )
    assert async_executor.fallback_attempts == 2

    # Check that traces on the second request recorded the route as blocked
    traces = getattr(response2, "traces", None)
    if traces is not None:
        has_blocked_trace = any(getattr(t, "wait_seconds", 0) > 0 for t in traces)
        assert has_blocked_trace, "Expected a blocked trace with wait_seconds > 0 in the second request"
